        data-pwa-card-name="{{ $contentTitle }}"
        data-pwa-card-balance="{{ $currentStamps }} / {{ $stampsRequired }} {{ trans('common.stamps') }}"
        data-pwa-card-qr="{{ $urlToCollectStamp }}"
    @endif
>

